'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{data=JSON.parse(localStorage.getItem('record.planner.lab.v1'));}catch{}data=data||demoData();let tab='Основное',sub='Настройки',preview=null,pending=null,ack=false;
const names=['Основное','Категории','Комплексы','Тайминг','Судьи','Статус'];
let config={date:data.event.date,workout:'w1',divs:['kids'],venue:'Площадка А',lanes:6,start:600,duration:10,gap:3,prepare:2};
const hh=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`,mins=s=>s.split(':').reduce((a,b)=>a*60+Number(b),0);
const field=(label,k,v,type='text',scope='event')=>`<label>${esc(label)}${type==='textarea'?`<textarea data-scope="${scope}" data-field="${k}">${esc(v)}</textarea>`:`<input type="${type}" data-scope="${scope}" data-field="${k}" value="${esc(v)}">`}</label>`;
const select=(label,k,v,opts,scope='event')=>`<label>${esc(label)}<select data-scope="${scope}" data-field="${k}">${opts.map(([id,n])=>`<option value="${esc(id)}" ${id===v?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
function message(s){$('notice').textContent=s;}
function save(){localStorage.setItem('record.planner.lab.v1',JSON.stringify(data));message('Черновик сохранён только в этом браузере.');}
function timingTable(){const rows=data.heats.flatMap((h,hi)=>h.slots.map(s=>{const w=data.event.workouts.find(x=>x.id===h.workout),d=data.event.divisions.find(x=>x.id===s.div);return {heat:hi+1,time:`${hh(h.start)}–${hh(h.start+h.duration)}`,lane:s.lane,name:s.name,category:d?.name||s.div,equipment:s.equipment||w?.equipment||w?.materials||'—',complex:w?.name||h.workout,venue:h.venue,status:({planned:'Запланирован',call:'Вызов',live:'Идёт',ended:'Завершён',cancelled:'Отменён'})[h.status]||h.status};}));return `<div class="table timing-table"><table><thead><tr><th>Заход</th><th>Время</th><th>№</th><th>Участник</th><th>Категория</th><th>Оборудование на дорожке</th><th>Комплекс</th><th>Площадка</th><th>Статус</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i===0||rows[i-1].heat!==r.heat?`<b>Заход ${r.heat}</b>`:''}</td><td>${i===0||rows[i-1].heat!==r.heat?r.time:''}</td><td>${r.lane}</td><td><b>${esc(r.name)}</b></td><td>${esc(r.category)}</td><td>${esc(r.equipment)}</td><td>${esc(r.complex)}</td><td>${esc(r.venue)}</td><td><span class="pill">${esc(r.status)}</span></td></tr>`).join('')||'<tr><td colspan="9">Заходы ещё не сформированы</td></tr>'}</tbody></table></div>`}

function schedule(athlete=false){const report=Planner.check(data,data.heats,data.windows),all=Planner.required(data);const mine=new Set(data.regs.filter(r=>r.owner==='demo-parent').map(r=>r.id));const opts=(rows,idKey='id',nameKey='name')=>'<option value="">Все</option>'+rows.map(r=>`<option value="${esc(r[idKey])}">${esc(r[nameKey])}</option>`).join('');
return `${athlete?`<div class="card grid"><label>Режим просмотра<select id="audience"><option value="parent">Родитель · мои и детские заходы</option><option value="guest">Гость · все заходы</option></select></label><label>Категория<select id="filterDiv">${opts(data.event.divisions)}</select></label><label>Комплекс<select id="filterWod">${opts(data.event.workouts)}</select></label><label>Площадка<input id="filterVenue" placeholder="Все"></label><label>Дата<input type="date" id="filterDate"></label><label>Фамилия<input id="searchName" placeholder="Поиск"></label></div>`:`<div class="stats"><div><b>${report.expected}</b><span>обязательных назначений</span></div><div><b>${report.assigned}</b><span>назначено</span></div><div><b>${report.missing.length}</b><span>не распределено</span></div><div><b>${report.lanes}</b><span>дорожек занято</span></div><div><b>${report.errors.length}</b><span>ошибок</span></div><div><b>${report.warnings.length}</b><span>предупреждений</span></div></div><div class="row actions"><button data-action="generate">Предложить распределение</button><button data-action="addHeat" class="ghost">+ Заход</button><button data-action="check" class="ghost">Проверить</button><button data-action="newReg" class="ghost">+ 27-й участник</button><button data-action="preview" class="ghost">Вид спортсмена</button></div><h3>Не распределены · ${report.missing.length}</h3>${report.missing.map(r=>{const rec=Planner.recommend(data,data.heats,r,data.windows);return `<div class="card"><b>${esc(r.name)}</b> · ${esc(r.div)} / ${esc(r.workout)}<p>${rec?'Рекомендуется '+esc(rec.heat.slice(-6))+' · дорожка '+rec.lane:'Свободного подходящего места нет — создайте дополнительный заход'}</p>${rec?`<button data-assign="${esc(Planner.key(r))}">Назначить</button>`:''}<button class="ghost" data-exclude="${esc(Planner.key(r))}">Обоснованное исключение</button></div>`}).join('')}`}
<div class="timeline" id="timeline">${[...data.windows.map(w=>({...w,window:true})),...data.heats].sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start).map(h=>h.window?`<div class="card"><b>${hh(h.start)}–${hh(h.start+h.duration)}</b> · ${esc(h.name)} · ${esc(h.venue||'Все площадки')}</div>`:`<details id="${h.id}" class="${h.slots.some(s=>mine.has(s.unit))?'mine':''}" data-heat="${h.id}" data-date="${h.date}" data-venue="${esc(h.venue)}" data-workout="${h.workout}" data-mine="${h.slots.some(s=>mine.has(s.unit))}"><summary>${hh(h.start)}–${hh(h.start+h.duration)} · ${esc(data.event.workouts.find(w=>w.id===h.workout)?.name)}<br><span class="muted">${esc(h.date)} · ${h.divs.map(id=>esc(data.event.divisions.find(d=>d.id===id)?.name)).join(', ')} · Заход ${data.heats.indexOf(h)+1} · ${esc(h.venue)} · ${h.slots.length}/${h.lanes}</span> <span class="pill">${esc(({planned:'Запланирован',call:'Вызов участников',live:'Идёт',ended:'Завершён',cancelled:'Отменён'})[h.status])}</span></summary>${!athlete?`<div class="grid">${field('Плановое начало','start',hh(h.start),'time','heat:'+h.id)}${select('Статус захода','status',h.status,[['planned','Запланирован'],['call','Вызов участников'],['live','Идёт'],['ended','Завершён'],['cancelled','Отменён']],'heat:'+h.id)}${field('Фактическое начало','actualStart',h.actualStart||'','time','heat:'+h.id)}${field('Фактическое окончание','actualEnd',h.actualEnd||'','time','heat:'+h.id)}</div>`:''}${h.slots.map(s=>`<div class="slot" data-div="${s.div}"><span class="pill">${s.lane}</span><strong>${esc(s.name)} ${s.manual?'✎':''}</strong><span class="muted">${esc(data.judges.find(j=>j.id===s.judge)?.name||'Судья не назначен')}</span>${!athlete?`<span>${s.paid?'Оплачен':'Ожидает оплаты'}</span><select aria-label="Судья для ${esc(s.name)}" data-judge="${h.id}" data-unit="${esc(s.unit)}"><option value="">Без судьи</option>${data.judges.map(j=>`<option value="${j.id}" ${j.id===s.judge?'selected':''}>${esc(j.name)}</option>`).join('')}</select><button class="ghost" data-move="${h.id}" data-unit="${esc(s.unit)}">Переместить / обменять</button>`:''}</div>`).join('')}</details>`).join('')||'<p class="muted">Заходы ещё не сформированы.</p>'}</div>${athlete?'':`<h3 id="checks">Проверка расписания</h3>${report.issues.map(i=>`<button class="ghost issue ${i.severity}" data-issue="${i.heat||''}">${esc(i.message)}</button>`).join('')||'<p>Конфликтов нет</p>'}<label><input type="checkbox" id="ack" ${ack?'checked':''}>Я ознакомился с предупреждениями</label><button data-action="publish">Подтвердить расписание в демо</button>`}`;}
function protocol(w){const logo=data.event.logo||'';const rows=data.event.divisions.filter(d=>w.divs.includes(d.id)).map(d=>`<tr><td>${esc(d.name)}</td><td></td><td></td><td></td><td></td></tr>`).join('');const html=`<!doctype html><meta charset="utf-8"><style>@page{size:A4;margin:15mm}body{font:12pt Arial;color:#111}header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #111;padding-bottom:12px}header img{max-height:55px;max-width:180px}h1{text-align:center;font-size:20pt}table{border-collapse:collapse;width:100%;margin-top:18px}td,th{border:1px solid #222;padding:7px;height:28px}small{color:#555}.left{float:left}.right{float:right}</style><header>${logo?`<img src="${esc(logo)}">`:''}<b class="left">№ 1 · Главный протокол</b><b class="right">№ 2 · Судейский экземпляр</b></header><h1>${esc(data.event.name)}<br>${esc(w.name)}</h1><p>${esc(w.description||'')}<br>Тип результата: ${esc(w.type)} · Таймкап: ${w.cap||'—'} сек.</p><table><thead><tr><th>Категория</th><th>Место</th><th>ФИО</th><th>Результат</th><th>Подпись судьи</th></tr></thead><tbody>${rows}</tbody></table>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'application/msword'}));a.download=`protokol-${w.name.replace(/[^\wа-яё-]+/gi,'-')}.doc`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function render(){const e=data.event;$('title').textContent=e.name;$('tabs').innerHTML=names.map(n=>`<button data-tab="${n}" aria-selected="${tab===n}">${n}</button>`).join('');let html='';
if(preview)html=`<button data-action="closePreview" class="ghost">← К редактору</button><h2>Предпросмотр расписания спортсмена</h2>${schedule(true)}`;
else if(tab==='Основное')html=`<h2>Основное</h2><div class="card grid">${[['Название','name'],['Подзаголовок','subtitle'],['Дата начала','date','date'],['Дата окончания','end','date'],['Город','city'],['Место','venue'],['Регистрация с','regFrom','date'],['Регистрация до','regTo','date'],['Возрастные правила','ageRule'],['URL обложки','cover'],['Описание','description','textarea'],['Дополнительные разделы','sections','textarea'],['Документы — ссылки и названия','docs','textarea'],['Условия возврата','refund','textarea']].map(([l,k,t])=>field(l,k,e[k],t)).join('')}${select('Формат','format',e.format,[['onsite','Очный'],['online','Онлайн']])}</div><button data-action="eventPreview">Предпросмотр соревнования</button><p class="muted">В прототипе файлы описываются ссылками. Загрузка файлов, действующие пресеты и расширенные правила остаются в текущем редакторе до интеграции.</p>`;
else if(tab==='Категории')html=`<h2>Категории</h2><button data-action="addDiv">+ Категория</button><button data-action="preset" class="ghost">Пресет: девочки 8–9 лет</button>${e.divisions.map(d=>`<details open><summary>${esc(d.name)} · ${Planner.units(data).filter(r=>r.div===d.id).length} / ${d.limit} · свободно ${Math.max(0,d.limit-Planner.units(data).filter(r=>r.div===d.id).length)}</summary><div class="grid">${field('Название','name',d.name,'text','div:'+d.id)}${select('Формат участия','type',d.type,[['ind','Личное первенство'],['team','Команда']],'div:'+d.id)}${select('Пол','gender',d.gender,[['M','Мужской'],['F','Женский'],['mix','Мужчины и женщины']],'div:'+d.id)}<div class="age-row">${field('Возраст от','ageMin',d.ageMin,'number','div:'+d.id)}${field('Возраст до','ageMax',d.ageMax,'number','div:'+d.id)}</div>${d.type==='team'?`${field('Количество в команде','size',d.size,'number','div:'+d.id)}${field('Состав и полы команды','mix',d.mix,'text','div:'+d.id)}`:''}${field('Дни выступления: от','daysFrom',d.daysFrom||d.days,'date','div:'+d.id)}${field('Дни выступления: до','daysTo',d.daysTo||d.days,'date','div:'+d.id)}${[['Лимит','limit','number'],['Стоимость','price','number'],['Примечание','note','textarea']].map(([l,k,t])=>field(l,k,d[k],t,'div:'+d.id)).join('')}</div><button class="ghost" data-delete-div="${d.id}">Удалить категорию</button></details>`).join('')}`;
else if(tab==='Комплексы')html=`<h2>Комплексы</h2>${select('Зачёт — существующая модель','scoring',e.scoring,[['places','Сумма мест'],['points','Баллы по таблице']])}<button data-action="addWod">+ Комплекс</button><button data-action="clearWod" class="ghost">Очистить форму нового комплекса</button>${e.workouts.map(w=>`<details open><summary>${esc(w.name)}</summary><div class="grid">${[['Название','name'],['Описание','description','textarea'],['Движения по порядку','movements','textarea'],['Стандарты','standards','textarea'],['Таймкап, секунд','cap','number'],['День','day','date'],['Примечания судье','judgeNotes','textarea'],['Материалы','materials','textarea']].map(([l,k,t])=>field(l,k,w[k],t,'wod:'+w.id)).join('')}${select('Результат','type',w.type,[['time','Время'],['reps','Повторения'],['load','Вес']],'wod:'+w.id)}${field('Категории (выберите ID через запятую)','divs',w.divs.join(','),'text','wod:'+w.id)}</div><div class="row"><button data-protocol="${w.id}" class="ghost">Протокол для печати (Word)</button></div><p class="muted">ID категории — технический идентификатор связи комплекса с категориями. Его можно выбрать из списка в основной версии.</p></details>`).join('')}`;
else if(tab==='Тайминг')html=`<div class="row">${['Настройки','Заходы','Общий тайминг'].map(n=>`<button data-sub="${n}" class="${sub===n?'':'ghost'}">${n}</button>`).join('')}</div>${sub==='Настройки'?`<div class="card grid">${[['Дата','date','date'],['Площадка','venue'],['Дорожек','lanes','number'],['Плановое начало в минутах от полуночи','start','number'],['Длительность, минут','duration','number'],['Переход, минут','gap','number'],['Подготовка оборудования, минут','prepare','number']].map(([l,k,t])=>field(l,k,config[k],t,'config')).join('')}${select('Комплекс','workout',config.workout,e.workouts.map(w=>[w.id,w.name]),'config')}${field('Категории в порядке распределения (ID через запятую)','divs',config.divs.join(','),'text','config')}</div><button data-action="addWindow" class="ghost">+ Перерыв / брифинг / награждение</button>`:''}${sub==='Общий тайминг'?`<div class="card"><h2>Итоговая таблица тайминга</h2><p class="muted">Строка соответствует участнику на конкретной дорожке. Таблица отсортирована по дате, времени и дорожке.</p>${timingTable()}</div>`:schedule()}`;
else if(tab==='Судьи'){const c=Planner.check(data,data.heats,data.windows);html=`<h2>Подтверждённая команда · демо</h2><p class="muted">Назначения не дают новых прав ввода результатов. Учёт смен, ставок и выплат остаётся в существующей панели.</p>${data.judges.map(j=>{const hs=data.heats.filter(h=>h.slots.some(s=>s.judge===j.id));return `<div class="card"><b>${esc(j.name)}</b> · ${j.role==='head_judge'?'Главный судья':'Судья'}<p>${hs.length} заходов · ${hs.reduce((n,h)=>n+h.duration,0)} минут плановой нагрузки</p>${hs.map(h=>`${hh(h.start)} · ${esc(h.venue)} · ${esc(h.workout)}`).join('<br>')}</div>`}).join('')}${c.issues.filter(i=>i.code.startsWith('judge')).map(i=>`<div class="error">${esc(i.message)}</div>`).join('')}<button data-action="judgeTiming">Назначения по дорожкам →</button>`;}
else html=`<h2>Статус старта</h2><p>Соревнование: ${esc(e.status)} · Расписание: ${esc(data.scheduleStatus)} · редакция ${data.revision}</p><div class="card">${[['draft','Черновик: виден только организатору'],['open','Регистрация открыта: старт виден, принимаются заявки'],['live','Идёт: доступен лидерборд и приём результатов по действующим правилам'],['ended','Завершён: регистрация закрыта, лидерборд сохраняется']].map(([v,l])=>`<p><button class="ghost" data-status="${v}">${l}</button></p>`).join('')}</div><h3>Готовность</h3><p>${e.name&&e.date?'✓':'✕'} Основное · ${e.divisions.length?'✓':'✕'} Категории · ${e.workouts.length?'✓':'✕'} Комплексы · ${Planner.check(data,data.heats,data.windows).errors.length} ошибок тайминга</p><p class="muted">Изменения статусов действуют только в демо.</p>`;
$('view').innerHTML=html;if(preview)filter();}
function filter(){const parent=$('audience').value==='parent',q=$('searchName').value.toLocaleLowerCase('ru'),d=$('filterDiv').value,w=$('filterWod').value,v=$('filterVenue').value.toLocaleLowerCase('ru'),date=$('filterDate').value;document.querySelectorAll('[data-heat]').forEach(el=>{const h=data.heats.find(h=>h.id===el.dataset.heat);el.hidden=(parent&&el.dataset.mine!=='true')||(w&&h.workout!==w)||(d&&!h.divs.includes(d))||(date&&h.date!==date)||!h.venue.toLocaleLowerCase('ru').includes(v)||(q&&!h.slots.some(s=>s.name.toLocaleLowerCase('ru').includes(q)));});}
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='ack'){ack=t.checked;return;}if(preview&&['audience','filterDiv','filterWod','filterVenue','filterDate'].includes(t.id)){filter();return;}if(t.dataset.judge){data.heats.find(h=>h.id===t.dataset.judge).slots.find(s=>s.unit===t.dataset.unit).judge=t.value;render();return;}if(!t.dataset.field)return;const [scope,id]=t.dataset.scope.split(':'),obj=scope==='event'?data.event:scope==='div'?data.event.divisions.find(d=>d.id===id):scope==='wod'?data.event.workouts.find(w=>w.id===id):scope==='heat'?data.heats.find(h=>h.id===id):config;const k=t.dataset.field;obj[k]=k==='divs'?t.value.split(',').map(s=>s.trim()).filter(Boolean):scope==='heat'&&k==='start'?mins(t.value):t.type==='number'?Number(t.value):t.value;data.scheduleStatus='draft';data.revision++;});
document.addEventListener('input',ev=>{if(preview&&['searchName','filterVenue'].includes(ev.target.id))filter();});
function proposal(plan){pending=plan;const r=Planner.check(data,plan,data.windows);$('proposalBody').innerHTML=`<p>${plan.length} заходов · ${r.assigned}/${r.expected} назначений · ${r.errors.length} ошибок · ${r.warnings.length} предупреждений</p><p>Существующие назначения, ручные перестановки и судьи сохранены. Новые места будут добавлены только после принятия.</p>${plan.map(h=>`<p>${hh(h.start)} · ${esc(h.venue)} · ${h.slots.length} участников</p>`).join('')}`;$('proposal').showModal();}
$('accept').onclick=()=>{data.heats=pending;data.scheduleStatus='draft';data.revision++;$('proposal').close();render();message('План принят в демо. Перед публикацией выполните проверку.');};$('reject').onclick=()=>{$('proposal').close();pending=null;};$('save').onclick=save;$('reset').onclick=()=>{if(confirm('Сбросить только демонстрационные данные?')){data=demoData();localStorage.removeItem('record.planner.lab.v1');render();}};
document.addEventListener('click',ev=>{const t=ev.target.closest('button');if(!t)return;try{if(t.dataset.protocol){protocol(data.event.workouts.find(w=>w.id===t.dataset.protocol));return;} if(t.dataset.tab){tab=t.dataset.tab;preview=null;render();return;}if(t.dataset.sub){sub=t.dataset.sub;render();return;}if(t.dataset.issue){const el=$(t.dataset.issue);if(el){el.open=true;el.scrollIntoView({block:'center'});}else document.querySelector('[data-assign]')?.scrollIntoView();return;}
if(t.dataset.move){const dest=prompt('Номер целевого захода (в списке)',String(data.heats.findIndex(h=>h.id===t.dataset.move)+1));if(dest===null)return;const lane=prompt('Номер дорожки (занятая дорожка — обмен)');if(lane===null)return;data.heats=Planner.move(data.heats,t.dataset.move,t.dataset.unit,data.heats[Number(dest)-1]?.id,Number(lane));render();return;}
if(t.dataset.assign){const r=Planner.required(data).find(r=>Planner.key(r)===t.dataset.assign),rec=Planner.recommend(data,data.heats,r,data.windows);if(!rec)throw Error('Нет безопасного места');data.heats.find(h=>h.id===rec.heat).slots.push({...r,lane:rec.lane,judge:'',manual:true});render();return;}
if(t.dataset.exclude){const reason=prompt('Обоснование исключения из расписания');if(reason?.trim()){data.exceptions.push({key:t.dataset.exclude,reason});render();}return;}
if(t.dataset.deleteDiv){if(data.regs.some(r=>r.div===t.dataset.deleteDiv)||data.heats.some(h=>h.divs.includes(t.dataset.deleteDiv)))throw Error('Удаление заблокировано: есть заявки или заходы');data.event.divisions=data.event.divisions.filter(d=>d.id!==t.dataset.deleteDiv);render();return;}
if(t.dataset.status){if(t.dataset.status!=='draft'&&(!data.event.name||!data.event.date||!data.event.divisions.length||!data.event.workouts.length))throw Error('Заполните основные данные, категории и комплексы');if(confirm(t.textContent+' — применить только в демо?')){data.event.status=t.dataset.status;render();}return;}
switch(t.dataset.action){case'generate':proposal(Planner.generate(data,config,data.heats));break;case'addHeat':data.heats.push({id:'heat-'+crypto.randomUUID(),date:config.date,workout:config.workout,divs:config.divs,venue:config.venue,lanes:config.lanes,start:config.start,duration:config.duration,gap:config.gap,status:'planned',slots:[]});render();break;case'newReg':if(data.regs.some(r=>r.id==='reg-27'))throw Error('27-й участник уже зарегистрирован');data.regs.push({id:'reg-27',personId:'person-27',div:'kids',name:'Новый Атлет 27',status:'new',owner:'other'});render();message('Новая заявка: участник не распределён. Рекомендация требует вашего подтверждения.');break;case'check':render();$('checks').scrollIntoView();break;case'publish':{const r=Planner.check(data,data.heats,data.windows);if(r.errors.length)throw Error('Нельзя подтвердить: '+r.errors.length+' ошибок');if(r.warnings.length&&!ack)throw Error('Подтвердите ознакомление с предупреждениями');data.scheduleStatus='published';save();message('Демонстрационное расписание подтверждено. Рабочий сайт не изменён.');break;}case'preview':preview=true;render();break;case'closePreview':preview=null;render();break;case'eventPreview':alert(`${data.event.name}\n${data.event.date} · ${data.event.city}\n${data.event.description}`);break;case'judgeTiming':tab='Тайминг';sub='Заходы';render();break;case'addDiv':case'preset':data.event.divisions.push({...data.event.divisions[0],id:'div-'+crypto.randomUUID(),name:t.dataset.action==='preset'?'Девочки 8–9 лет':'Новая категория',gender:t.dataset.action==='preset'?'F':'M'});render();break;case'clearWod':{data.event.workouts.push({id:'w-'+crypto.randomUUID(),name:'Новый комплекс',description:'',movements:'',standards:'',cap:600,day:data.event.date,judgeNotes:'',materials:'',type:'time',divs:[]});render();break;}case'addWod':data.event.workouts.push({...data.event.workouts[0],id:'w-'+crypto.randomUUID(),name:'Новый комплекс'});render();break;case'addWindow':{const name=prompt('Название: перерыв, брифинг, награждение');if(!name)return;const start=prompt('Начало ЧЧ:ММ','12:00'),duration=Number(prompt('Длительность, минут','20'));if(!start||!Number.isFinite(mins(start))||!(duration>0))throw Error('Неверное время');data.windows.push({id:crypto.randomUUID(),date:config.date,venue:config.venue,name,start:mins(start),duration});render();break;}}
}catch(e){message(e.message);}});
render();
